idence_ids":[1]},{"claim_text":"Reform of the 42-year old National Environmental Policy Act should limit litigation against infrastructure projects.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Securing sufficient funding for the Highway Trust Fund remains a challenge given the debt and deficits and the need to reduce spending.", "claim_types":["factual_assertion"],"evidence_ids":[2]},{"claim_text":"Republicans will make hard choices and set priorities, and infrastructure will be among them.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"In some States with elected officials dominated by the Democratic Party, a proportion of highway funds is diverted to other purposes, and this must stop.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"Republicans oppose any funding mechanism that would involve governmental monitoring of every car and truck in the nation.", "claim_types":["policy_position"],"evidence_ids":[2]}],"unresolved_references":[]}
